package com.insight.quantlife.tests;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.net.Uri;import android.provider.MediaStore;import android.view.accessibility.*;import org.json.*;import java.io.*;
/** Real button -> Android document picker -> content resolver -> native image event. Synthetic only. */
public class ImagePickerFlowTest extends DocumentEditorTest {
 String filename="ZhishiPicker-"+System.currentTimeMillis()+".png";
 Uri seed()throws Exception{ContentValues v=new ContentValues();v.put(MediaStore.Images.Media.DISPLAY_NAME,filename);v.put(MediaStore.Images.Media.MIME_TYPE,"image/png");v.put(MediaStore.Images.Media.RELATIVE_PATH,"Pictures/ZhishiTests");Uri uri=getTargetContext().getContentResolver().insert(MediaStore.Images.Media.EXTERNAL_CONTENT_URI,v);Bitmap b=Bitmap.createBitmap(360,180,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(b);c.drawColor(0xffcdddaf);Paint p=new Paint();p.setColor(0xff216a54);p.setTextSize(24);c.drawText("Real system picker",15,100,p);try(OutputStream out=getTargetContext().getContentResolver().openOutputStream(uri)){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();return uri;}
 String tree(AccessibilityNodeInfo n){if(n==null)return "";StringBuilder b=new StringBuilder();b.append(n.getPackageName()).append(' ').append(n.getText()).append(' ').append(n.getContentDescription()).append('\n');for(int i=0;i<n.getChildCount();i++)b.append(tree(n.getChild(i)));return b.toString();}
 boolean chooseNode(AccessibilityNodeInfo root,String name){if(root==null)return false;String text=String.valueOf(root.getText()),desc=String.valueOf(root.getContentDescription());if((text.contains(name)||desc.contains(name))&&!desc.toLowerCase().contains("preview")&&root.isVisibleToUser()){if(root.performAction(AccessibilityNodeInfo.ACTION_CLICK))return true;root.performAction(AccessibilityNodeInfo.ACTION_FOCUS);long now=SystemClock.uptimeMillis();getUiAutomation().injectInputEvent(new android.view.KeyEvent(now,now,android.view.KeyEvent.ACTION_DOWN,android.view.KeyEvent.KEYCODE_ENTER,0),true);getUiAutomation().injectInputEvent(new android.view.KeyEvent(now,SystemClock.uptimeMillis(),android.view.KeyEvent.ACTION_UP,android.view.KeyEvent.KEYCODE_ENTER,0),true);return true;}for(int i=0;i<root.getChildCount();i++)if(chooseNode(root.getChild(i),name))return true;return false;}
 boolean choose(String name)throws Exception{for(int i=0;i<50;i++){if(chooseNode(getUiAutomation().getRootInActiveWindow(),name))return true;Thread.sleep(100);}return false;}
 void waitPicker()throws Exception{for(int i=0;i<100;i++){if(tree(getUiAutomation().getRootInActiveWindow()).contains("com.android.documentsui")){Thread.sleep(400);return;}Thread.sleep(100);}throw new Exception("System picker not yet visible");}
 void launchPicker()throws Exception{h.tap("#doc-image",false);until("!!document.querySelector('#image-local-tab')");click("#image-local-tab");h.tap("#image-local-pick",false);}
 @Override public void onStart(){Bundle result=new Bundle();try{
  seed();h=new MainHost(this);h.open();h.js("AutoWiki.kick=()=>{};AutoWiki.resume=()=>{}");open("learning");StringBuilder longNote=new StringBuilder();for(int i=0;i<90;i++)longNote.append("第"+i+"段：这是长篇合成笔记，用于验证滚动位置与插入光标不会丢失。\n");input("系统选图流程验证",longNote.toString());
  h.js("window.__pickerCalls=[];window.__buttonEvents=[];window.__pickerNative=LifeNative;LifeNative={call:(a,p,id)=>{if(a==='pick')__pickerCalls.push(JSON.parse(p));__pickerNative.call(a,p,id)}};['pointerdown','pointerup','click','touchstart','touchend'].forEach(t=>document.querySelector('#doc-image').addEventListener(t,e=>__buttonEvents.push(t)));(()=>{const b=document.querySelector('#doc-body'),r=document.createRange();b.focus();r.setStart(b.firstChild,1600);r.collapse(true);getSelection().removeAllRanges();getSelection().addRange(r);document.dispatchEvent(new Event('selectionchange'));})()");Thread.sleep(700);launchPicker();Thread.sleep(1300);
  String recordId=new JSONArray(h.js("[__pickerCalls[0].recordId]")).getString(0);
  check(h.js("__pickerCalls.length===1").equals("true"),"Native touch with keyboard open launches picker once; events="+h.js("__buttonEvents"));
  String ui="";for(int i=0;i<80;i++){ui=tree(getUiAutomation().getRootInActiveWindow());if(ui.contains("documentsui"))break;Thread.sleep(100);}check(ui.contains("documentsui"),"Actual Android document picker opens: "+ui.substring(0,Math.min(200,ui.length())));h.screenshot("system-image-picker.png");
  check(choose(filename),"Synthetic image is selectable in actual system document picker");until("document.querySelectorAll('#doc-body img').length===1&&document.querySelector('#doc-body img').naturalWidth>0");check(h.js("DocumentRich.serialize(document.querySelector('#doc-body'))").contains("zhishi-media:"),"Native import callback inserts visible image token into note");h.screenshot("system-image-inserted.png");
  until("(()=>{const r=document.querySelector('#doc-body img').getBoundingClientRect(),v=document.querySelector('#doc-edit-scroll').getBoundingClientRect();return Math.min(r.bottom,v.bottom)-Math.max(r.top,v.top)>=Math.min(r.height,v.height)*.8})()");check(true,"At least 80% of inserted image is visible after keyboard settles");h.screenshot("system-image-inserted.png");
  if(phase.equals("duplicate")){launchPicker();Thread.sleep(1000);check(choose(filename),"Same file can be selected again");Thread.sleep(1200);check(h.js("document.querySelectorAll('#doc-body img').length===2").equals("true"),"Same stored image can be inserted at another position");}
  if(phase.equals("clip")){java.lang.reflect.Method callback=h.activity.getClass().getDeclaredMethod("onActivityResult",int.class,int.class,Intent.class);callback.setAccessible(true);Intent clip=new Intent();clip.setClipData(ClipData.newRawUri("synthetic",seed()));runOnMainSync(()->{try{callback.invoke(h.activity,10,Activity.RESULT_OK,clip);}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(1200);check(h.js("document.querySelectorAll('#doc-body img').length===2").equals("true"),"ClipData-only picker result inserts image instead of silently discarding it");}
  if(phase.equals("recreate")){launchPicker();waitPicker();ActivityMonitor monitor=addMonitor("com.insight.quantlife.MainActivity",null,false);runOnMainSync(()->h.activity.recreate());Thread.sleep(1000);check(choose(filename),"Choose image after system recreates editor activity");Activity next=waitForMonitorWithTimeout(monitor,5000);removeMonitor(monitor);check(next!=null&&next!=h.activity,"Real activity recreated while picker is open");h.activity=next;java.lang.reflect.Field wf=next.getClass().getDeclaredField("web");wf.setAccessible(true);h.web=(android.webkit.WebView)wf.get(next);until("document.querySelectorAll('#doc-body img').length===2");check(h.js("RecordDocument.plain(DocumentRich.serialize(document.querySelector('#doc-body')))").equals(JSONObject.quote(longNote.toString().replaceAll("\\s", ""))),"Recreation restores complete long draft and both images");}
  int imageCount=new JSONArray(h.js("Array.from(document.querySelectorAll('#doc-body img')).map(i=>i.src)")).length();String id=recordId;
  check(h.js("RecordDocument.plain(DocumentRich.serialize(document.querySelector('#doc-body')))").equals(JSONObject.quote(longNote.toString().replaceAll("\\s", ""))),"Inserting preserves every character of long note");check(h.call("pendingRecordImage",new JSONObject())==JSONObject.NULL,"Delivery acknowledged only after durable draft save");JSONArray pendingDrafts=(JSONArray)h.call("getDocumentDraft",new JSONObject());JSONObject delivery=null;for(int j=0;j<pendingDrafts.length();j++)if(pendingDrafts.getJSONObject(j).getJSONObject("record").getString("id").equals(id))delivery=pendingDrafts.getJSONObject(j).getJSONObject("record").getJSONArray("images").getJSONObject(0);h.js("window.__replayed=false;Promise.all([RecordEditor.image("+delivery+"),RecordEditor.image("+delivery+")]).then(()=>__replayed=true)");until("__replayed");check(h.js("document.querySelectorAll('#doc-body img').length==="+imageCount).equals("true"),"Concurrent duplicate callbacks do not insert the same delivery twice");saveUI();JSONObject saved=record(id);h.js("RecordEditor.open("+saved+")");until("document.querySelectorAll('#doc-body img').length==="+imageCount+"&&Array.from(document.querySelectorAll('#doc-body img')).every(i=>i.naturalWidth>0)");check(true,"All inserted image references survive save and reopen");
  if(phase.equals("duplicate")){click("[data-remove-image]");check(h.js("document.querySelectorAll('#doc-body img').length===1").equals("true"),"Removing one repeated image keeps the other placement");click("#doc-undo");check(h.js("document.querySelectorAll('#doc-body img').length===2").equals("true"),"Undo restores both repeated image placements");}
  result.putString("stream","PASS ImagePickerFlowTest "+phase+": "+passed+" checks\n");finish(Activity.RESULT_OK,result);
 }catch(Throwable err){try{if(h!=null)h.screenshot("image-picker-failure.png");}catch(Exception ignored){}result.putString("stream","FAIL ImagePickerFlowTest after "+passed+": "+err+" cause="+err.getCause()+"; UI="+tree(getUiAutomation().getRootInActiveWindow())+"\n");finish(Activity.RESULT_CANCELED,result);}}
}
